/**
 * Satisfaction transitions — deterministic downstream of the classifier.
 * Three marker types, each a distinct once-but-critical signal:
 *   milestone:  neutral -> pleased   (task completed to the user's satisfaction)
 *   recovery:   displeased -> ... -> pleased (something failed, then got fixed)
 *   regression: pleased -> displeased (something that worked broke)
 * A displeased run that never resolves by session end is reported as
 * `unresolved` (the highest-value capture: a failure that survived).
 *
 * Pure function over verdicts; no inference, no I/O.
 */
import type { TurnVerdict } from './satisfaction-classifier';

export type TransitionKind = 'milestone' | 'recovery' | 'regression' | 'unresolved';

export interface SatisfactionTransition {
  kind: TransitionKind;
  /** index before the state change, or first displeased turn for recovery/unresolved */
  fromIndex: number;
  /** index of the turn where the new state is observed */
  toIndex: number;
}

export function detectTransitions(verdicts: TurnVerdict[]): SatisfactionTransition[] {
  const transitions: SatisfactionTransition[] = [];

  let prev: TurnVerdict | null = null;
  let displeasedFrom: number | null = null; // index of the FIRST displeased turn of the open run

  for (const turn of verdicts) {
    if (turn.state === 'displeased' && displeasedFrom === null) {
      displeasedFrom = turn.index; // a displeased run starts (kept at its first turn)
    }
    if (prev !== null && turn.state !== prev.state) {
      if (turn.state === 'pleased') {
        if (displeasedFrom !== null) {
          // Satisfaction closes the open run even when neutral turns intervene.
          transitions.push({ kind: 'recovery', fromIndex: displeasedFrom, toIndex: turn.index });
          displeasedFrom = null;
        } else if (prev.state === 'neutral') {
          transitions.push({ kind: 'milestone', fromIndex: prev.index, toIndex: turn.index });
        }
      } else if (turn.state === 'displeased') {
        if (prev.state === 'pleased') {
          transitions.push({ kind: 'regression', fromIndex: prev.index, toIndex: turn.index });
        }
        // displeasedFrom already set above at run start; never overwrite mid-run
      }
    }
    prev = turn;
  }

  if (displeasedFrom !== null) {
    const lastIndex = verdicts.length > 0 ? verdicts[verdicts.length - 1].index : displeasedFrom;
    transitions.push({ kind: 'unresolved', fromIndex: displeasedFrom, toIndex: lastIndex });
  }
  return transitions;
}

import { expect, test } from 'bun:test';
import { detectTransitions } from '../src/satisfaction-transitions';
import type { TurnVerdict } from '../src/satisfaction-classifier';

const v = (index: number, state: TurnVerdict['state']): TurnVerdict => ({ index, state });

test('neutral between displeasure and satisfaction closes exactly one recovery', () => {
  expect(detectTransitions([
    v(0, 'displeased'), v(1, 'neutral'), v(2, 'pleased'),
  ])).toEqual([{ kind: 'recovery', fromIndex: 0, toIndex: 2 }]);
});

test('repeated displeasure and neutral turns retain the first failure index', () => {
  expect(detectTransitions([
    v(4, 'displeased'), v(7, 'neutral'), v(9, 'displeased'),
    v(12, 'neutral'), v(16, 'neutral'), v(20, 'pleased'),
    v(21, 'pleased'), v(25, 'neutral'),
  ])).toEqual([{ kind: 'recovery', fromIndex: 4, toIndex: 20 }]);
});

test('later displeasure starts a separate run after a neutral-spanning recovery', () => {
  expect(detectTransitions([
    v(0, 'displeased'), v(1, 'neutral'), v(2, 'pleased'),
    v(3, 'displeased'), v(4, 'neutral'), v(5, 'pleased'),
  ])).toEqual([
    { kind: 'recovery', fromIndex: 0, toIndex: 2 },
    { kind: 'regression', fromIndex: 2, toIndex: 3 },
    { kind: 'recovery', fromIndex: 3, toIndex: 5 },
  ]);
});

test('a later unresolved run uses its own start and the terminal neutral turn', () => {
  expect(detectTransitions([
    v(0, 'displeased'), v(1, 'neutral'), v(2, 'pleased'),
    v(3, 'neutral'), v(4, 'displeased'), v(5, 'neutral'),
  ])).toEqual([
    { kind: 'recovery', fromIndex: 0, toIndex: 2 },
    { kind: 'unresolved', fromIndex: 4, toIndex: 5 },
  ]);
});

test('ordinary milestones remain available before and after a recovery', () => {
  expect(detectTransitions([
    v(0, 'neutral'), v(1, 'pleased'), v(2, 'displeased'),
    v(3, 'neutral'), v(4, 'pleased'), v(5, 'neutral'), v(6, 'pleased'),
  ])).toEqual([
    { kind: 'milestone', fromIndex: 0, toIndex: 1 },
    { kind: 'regression', fromIndex: 1, toIndex: 2 },
    { kind: 'recovery', fromIndex: 2, toIndex: 4 },
    { kind: 'milestone', fromIndex: 5, toIndex: 6 },
  ]);
});

test('neutral turns alone do not resolve an open failure', () => {
  expect(detectTransitions([
    v(3, 'displeased'), v(5, 'neutral'), v(7, 'displeased'), v(9, 'neutral'),
  ])).toEqual([{ kind: 'unresolved', fromIndex: 3, toIndex: 9 }]);
});
